const e="FO1rII573ho",t="ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice",c="b1",n="Learn English with SLOW Interviews (comprehensible input) - B1+ interview practice",i="https://www.youtube.com/watch?v=FO1rII573ho",r={podcastLabel:"MissHoney B1",titleZh:"透過 SLOW Interviews 學習英語（可理解的輸入）- B1+ 面試練習",titleEn:"Learn English with SLOW Interviews (comprehensible input) - B1+ interview practice",levelTag:"B1",topicTag:"work"},a=JSON.parse(`[{"id":"scene-01","no":"01","titleZh":"第 1 段","titleEn":"Part 1","sentences":[{"en":"Where do you see yourself in five years?","tc":"你覺得五年後的自己會在哪裡？","englishTokens":[{"type":"text","text":"Where do you "},{"type":"phrase","text":"see yourself in five years","targetId":"phrase-see-yourself-in-five-years","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-001-01"},{"type":"text","text":"?"}]},{"en":"So You Don't Have To: Essential job interview vocabulary.","tc":"《So You Don't Have To：求職面試必備詞彙》。","englishTokens":[{"type":"text","text":"So You Don't Have To: "},{"type":"word","text":"Essential","targetId":"word-essential","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-002-01"},{"type":"text","text":" "},{"type":"phrase","text":"job interview","targetId":"phrase-job-interview","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-002-02"},{"type":"text","text":" "},{"type":"word","text":"vocabulary","targetId":"word-vocabulary","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-002-03"},{"type":"text","text":"."}]},{"en":"Hello, and welcome back to my slow English podcast.","tc":"哈囉，歡迎回到我的慢速英語 Podcast。","englishTokens":[{"type":"text","text":"Hello, and welcome back to my slow English "},{"type":"word","text":"podcast","targetId":"word-podcast","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-003-01"},{"type":"text","text":"."}]},{"en":"Today, I'm excited to have another slow English interview with my sister.","tc":"今天我很高興能和我妹妹再做一次慢速英語訪談。","englishTokens":[{"type":"text","text":"Today, I'm excited to have another slow English interview with my sister."}]}],"tags":[]},{"id":"scene-02","no":"02","titleZh":"第 2 段","titleEn":"Part 2","sentences":[{"en":"We will practice asking questions and answering them with new vocabulary essential for a job interview.","tc":"我們會練習用求職面試必備的新詞彙來提問和回答。","englishTokens":[{"type":"text","text":"We will practice asking questions and answering them with new "},{"type":"word","text":"vocabulary","targetId":"word-vocabulary","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-005-01"},{"type":"text","text":" essential for a "},{"type":"phrase","text":"job interview","targetId":"phrase-job-interview","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-005-02"},{"type":"text","text":"."}]},{"en":"You can practice your English listening skills by listening to slow English conversations.","tc":"你可以透過聽慢速英語對話來練習英文聽力技巧。","englishTokens":[{"type":"text","text":"You can practice your English "},{"type":"phrase","text":"listening skills","targetId":"phrase-listening-skills","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-006-01"},{"type":"text","text":" by listening to slow English conversations."}]},{"en":"I personally get really nervous at job interviews, even though I'm a hard worker and a good learner, and I'm always on time.","tc":"我個人在求職面試時真的很緊張，即使我是個努力工作的人、學習能力也好，而且總是準時。","englishTokens":[{"type":"text","text":"I personally get really nervous at "},{"type":"phrase","text":"job interviews","targetId":"phrase-job-interview","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-007-01"},{"type":"text","text":", even though I'm a "},{"type":"phrase","text":"hard worker","targetId":"phrase-hard-worker","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-007-02"},{"type":"text","text":" and a good learner, and I'm always "},{"type":"phrase","text":"on time","targetId":"phrase-on-time","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-007-03"},{"type":"text","text":"."}]},{"en":"The interviewer doesn't know any of that.","tc":"面試官不知道那些事。","englishTokens":[{"type":"text","text":"The "},{"type":"word","text":"interviewer","targetId":"word-interviewer","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-008-01"},{"type":"text","text":" doesn't know any of that."}]}],"tags":[]},{"id":"scene-03","no":"03","titleZh":"第 3 段","titleEn":"Part 3","sentences":[{"en":"The interviewer has to determine if you're a good worker or a bad worker.","tc":"面試官必須判斷你是好員工還是壞員工。","englishTokens":[{"type":"text","text":"The "},{"type":"word","text":"interviewer","targetId":"word-interviewer","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-009-01"},{"type":"text","text":" has to determine if you're a good worker or a bad worker."}]},{"en":"They need to determine if you have extensive experience or minimal experience.","tc":"他們需要判斷你是有豐富經驗還是經驗很少。","englishTokens":[{"type":"text","text":"They need to determine if you have "},{"type":"word","text":"extensive","targetId":"word-extensive","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-010-01"},{"type":"text","text":" experience or "},{"type":"word","text":"minimal","targetId":"word-minimal","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-010-02"},{"type":"text","text":" experience."}]},{"en":"I will act as the interviewer, and Bri will act as the interviewee.","tc":"我會扮演面試官，Bri 會扮演受訪者。","englishTokens":[{"type":"text","text":"I will act as the "},{"type":"word","text":"interviewer","targetId":"word-interviewer","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-011-01"},{"type":"text","text":", and Bri will act as the "},{"type":"word","text":"interviewee","targetId":"word-interviewee","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-011-02"},{"type":"text","text":"."}]},{"en":"So, can you tell me a little bit about yourself?","tc":"所以，你可以簡單介紹一下自己嗎？","englishTokens":[{"type":"text","text":"So, can you tell me "},{"type":"phrase","text":"a little bit","targetId":"phrase-a-little-bit","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-012-01"},{"type":"text","text":" about yourself?"}]}],"tags":[]},{"id":"scene-04","no":"04","titleZh":"第 4 段","titleEn":"Part 4","sentences":[{"en":"Yes.","tc":"可以。","englishTokens":[{"type":"text","text":"Yes."}]},{"en":"My name is Brianna Ortiz.","tc":"我的名字是 Brianna Ortiz。","englishTokens":[{"type":"text","text":"My name is Brianna Ortiz."}]},{"en":"I have a bachelor's degree in physics from the University of Puebla.","tc":"我有普埃布拉大學物理學士學位。","englishTokens":[{"type":"text","text":"I have a "},{"type":"phrase","text":"bachelor's degree","targetId":"phrase-bachelor-s-degree","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-015-01"},{"type":"text","text":" in "},{"type":"word","text":"physics","targetId":"word-physics","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-015-02"},{"type":"text","text":" from the University of Puebla."}]},{"en":"For work, I have a background in English teaching.","tc":"工作方面，我有英語教學背景。","englishTokens":[{"type":"text","text":"For work, I "},{"type":"phrase","text":"have a background in","targetId":"phrase-have-a-background-in","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-016-01"},{"type":"text","text":" English teaching."}]}],"tags":[]},{"id":"scene-05","no":"05","titleZh":"第 5 段","titleEn":"Part 5","sentences":[{"en":"I've been an English teacher for five years.","tc":"我當英文老師已經五年了。","englishTokens":[{"type":"text","text":"I've been an English teacher for five years."}]},{"en":"This year, I started with Spanish teaching and copywriting.","tc":"今年我開始做西班牙文教學和文案寫作。","englishTokens":[{"type":"text","text":"This year, I started with Spanish teaching and "},{"type":"word","text":"copywriting","targetId":"word-copywriting","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-018-01"},{"type":"text","text":"."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"I have experience teaching kids based in China from grades K through 12.","tc":"我有教在中國、K 到 12 年級孩子的經驗。","englishTokens":[{"type":"text","text":"I have experience teaching kids "},{"type":"phrase","text":"based in","targetId":"phrase-based-in","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-020-01"},{"type":"text","text":" China from grades "},{"type":"phrase","text":"K through 12","targetId":"phrase-k-through-12","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-020-02"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-06","no":"06","titleZh":"第 6 段","titleEn":"Part 6","sentences":[{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"Some of my hobbies are going to the gym, learning languages, um, and drawing.","tc":"我的一些興趣是去健身房、學語言，呃，還有畫畫。","englishTokens":[{"type":"text","text":"Some of my "},{"type":"word","text":"hobbies","targetId":"word-hobby","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-022-01"},{"type":"text","text":" are going to the gym, learning languages, um, and drawing."}]},{"en":"And what do we mean when we say background, that we have a background in something?","tc":"當我們說 background，說我們在某方面有 background 時，是什麼意思？","englishTokens":[{"type":"text","text":"And what do we mean when we say "},{"type":"usage","text":"background","targetId":"usage-background-item","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-023-01"},{"type":"text","text":", that we have a background in something?"}]},{"en":"When we use background, it's usually for your past experience with jobs or studies.","tc":"當我們使用 background 時，通常是指你過去在工作或學業上的經驗。","englishTokens":[{"type":"text","text":"When we use "},{"type":"usage","text":"background","targetId":"usage-background-item","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-scene-06-004-001"},{"type":"text","text":", it's usually for your past experience with jobs or studies."}]}],"tags":[]},{"id":"scene-07","no":"07","titleZh":"第 7 段","titleEn":"Part 7","sentences":[{"en":"And what does it mean when we talk about experience?","tc":"那當我們談到 experience 時，是什麼意思？","englishTokens":[{"type":"text","text":"And what does it mean when we talk about experience?"}]},{"en":"Experience might be the time you've spent on a job and maybe the skills you've gained along the way.","tc":"Experience 可能是你花在一份工作上的時間，也可能是你一路上獲得的技能。","englishTokens":[{"type":"text","text":"Experience might be the time you've spent on a job and maybe the skills you've gained "},{"type":"phrase","text":"along the way","targetId":"phrase-along-the-way","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-026-01"},{"type":"text","text":"."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"And why do you want this job?","tc":"那你為什麼想要這份工作？","englishTokens":[{"type":"text","text":"And why do you want this job?"}]}],"tags":[]},{"id":"scene-08","no":"08","titleZh":"第 8 段","titleEn":"Part 8","sentences":[{"en":"Well, I really enjoy working with people.","tc":"嗯，我真的很喜歡和人一起工作。","englishTokens":[{"type":"text","text":"Well, I really enjoy working with people."}]},{"en":"I love talking to people, getting to know people, especially children.","tc":"我喜歡跟人說話、認識人，尤其是孩子。","englishTokens":[{"type":"text","text":"I love talking to people, "},{"type":"phrase","text":"getting to know","targetId":"phrase-get-to-know","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-030-01"},{"type":"text","text":" people, especially children."}]},{"en":"I love helping in the learning process and learning myself as we move along.","tc":"我喜歡在學習過程中幫忙，也喜歡隨著進展一起學習。","englishTokens":[{"type":"text","text":"I love helping in the "},{"type":"phrase","text":"learning process","targetId":"phrase-learning-process","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-031-01"},{"type":"text","text":" and learning myself as we "},{"type":"phrase","text":"move along","targetId":"phrase-move-along","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-031-02"},{"type":"text","text":"."}]},{"en":"Some of my interests are in the science area.","tc":"我的一些興趣在科學領域。","englishTokens":[{"type":"text","text":"Some of my interests are in the science "},{"type":"usage","text":"area","targetId":"usage-area-item","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-032-01"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-09","no":"09","titleZh":"第 9 段","titleEn":"Part 9","sentences":[{"en":"So, I would love to teach English biology, English physics, or even English chemistry.","tc":"所以，我很想教英文生物、英文物理，甚至英文化學。","englishTokens":[{"type":"text","text":"So, I would love to teach English biology, English "},{"type":"word","text":"physics","targetId":"word-physics","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-scene-09-001-001"},{"type":"text","text":", or even English chemistry."}]},{"en":"Some of my goals are to become a better teacher, become a more knowledgeable person, and create a classroom environment that is welcoming for everyone.","tc":"我的一些目標是成為更好的老師、成為知識更豐富的人，並創造一個對每個人都友善歡迎的教室環境。","englishTokens":[{"type":"text","text":"Some of my goals are to become a better teacher, become a more "},{"type":"word","text":"knowledgeable","targetId":"word-knowledgeable","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-034-01"},{"type":"text","text":" person, and create a classroom "},{"type":"word","text":"environment","targetId":"word-environment","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-034-02"},{"type":"text","text":" that is welcoming for everyone."}]},{"en":"And my core values are honesty, loyalty, and patience more than anything.","tc":"而我的核心價值最重要的是誠實、忠誠和耐心。","englishTokens":[{"type":"text","text":"And my "},{"type":"phrase","text":"core values","targetId":"phrase-core-values","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-035-01"},{"type":"text","text":" are "},{"type":"word","text":"honesty","targetId":"word-honesty","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-035-02"},{"type":"text","text":", "},{"type":"word","text":"loyalty","targetId":"word-loyalty","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-035-03"},{"type":"text","text":", and "},{"type":"word","text":"patience","targetId":"word-patience","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-035-04"},{"type":"text","text":" more than anything."}]},{"en":"Good answer.","tc":"好答案。","englishTokens":[{"type":"text","text":"Good answer."}]}],"tags":[]},{"id":"scene-10","no":"10","titleZh":"第 10 段","titleEn":"Part 10","sentences":[{"en":"So, what are your greatest strengths?","tc":"那麼，你最大的優點是什麼？","englishTokens":[{"type":"text","text":"So, what are your greatest "},{"type":"word","text":"strengths","targetId":"word-strength","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-037-01"},{"type":"text","text":"?"}]},{"en":"I am organized.","tc":"我有條理。","englishTokens":[{"type":"text","text":"I am organized."}]},{"en":"I am punctual.","tc":"我很準時。","englishTokens":[{"type":"text","text":"I am "},{"type":"word","text":"punctual","targetId":"word-punctual","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-039-01"},{"type":"text","text":"."}]},{"en":"I am, I am a good team leader.","tc":"我是，我是一個好的團隊領導者。","englishTokens":[{"type":"text","text":"I am, I am a good "},{"type":"phrase","text":"team leader","targetId":"phrase-team-leader","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-040-01"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-11","no":"11","titleZh":"第 11 段","titleEn":"Part 11","sentences":[{"en":"And I am very thorough with my work.","tc":"而且我對工作非常仔細。","englishTokens":[{"type":"text","text":"And I am very "},{"type":"word","text":"thorough","targetId":"word-thorough","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-041-01"},{"type":"text","text":" with my work."}]},{"en":"What does it mean to be a thorough worker?","tc":"當一個 thorough worker 是什麼意思？","englishTokens":[{"type":"text","text":"What does it mean to be a "},{"type":"word","text":"thorough","targetId":"word-thorough","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-scene-11-002-001"},{"type":"text","text":" worker?"}]},{"en":"To be exhaustive.","tc":"就是很徹底。","englishTokens":[{"type":"text","text":"To be "},{"type":"word","text":"exhaustive","targetId":"word-exhaustive","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-043-01"},{"type":"text","text":"."}]},{"en":"To take something from beginning to end.","tc":"把一件事從頭做到尾。","englishTokens":[{"type":"text","text":"To take something from beginning to end."}]}],"tags":[]},{"id":"scene-12","no":"12","titleZh":"第 12 段","titleEn":"Part 12","sentences":[{"en":"Very complete.","tc":"非常完整。","englishTokens":[{"type":"text","text":"Very complete."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"What do you think are some of your weaknesses?","tc":"你認為自己有哪些弱點？","englishTokens":[{"type":"text","text":"What do you think are some of your "},{"type":"word","text":"weaknesses","targetId":"word-weakness","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-047-01"},{"type":"text","text":"?"}]},{"en":"Sometimes I can get very nervous.","tc":"有時候我會很緊張。","englishTokens":[{"type":"text","text":"Sometimes I can get very nervous."}]}],"tags":[]},{"id":"scene-13","no":"13","titleZh":"第 13 段","titleEn":"Part 13","sentences":[{"en":"I am very soft-spoken, so sometimes my ideas aren't heard.","tc":"我說話很溫和，所以有時候我的想法不會被聽見。","englishTokens":[{"type":"text","text":"I am very "},{"type":"word","text":"soft-spoken","targetId":"word-soft-spoken","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-049-01"},{"type":"text","text":", so sometimes my ideas aren't heard."}]},{"en":"This can sometimes show in classroom management.","tc":"這有時會表現在班級經營上。","englishTokens":[{"type":"text","text":"This can sometimes "},{"type":"usage","text":"show","targetId":"usage-show-item","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-050-01"},{"type":"text","text":" in "},{"type":"phrase","text":"classroom management","targetId":"phrase-classroom-management","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-050-02"},{"type":"text","text":"."}]},{"en":"I don't like yelling.","tc":"我不喜歡吼叫。","englishTokens":[{"type":"text","text":"I don't like yelling."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]}],"tags":[]},{"id":"scene-14","no":"14","titleZh":"第 14 段","titleEn":"Part 14","sentences":[{"en":"So sometimes kids can go crazy.","tc":"所以有時候小孩會失控。","englishTokens":[{"type":"text","text":"So sometimes kids can go crazy."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"Sometimes I can be a bit of a perfectionist, so I will go past deadlines in order to make the work exactly how I want it.","tc":"有時候我可能有點完美主義，所以我會超過截止期限，為了把作品做到完全符合我想要的樣子。","englishTokens":[{"type":"text","text":"Sometimes I can be "},{"type":"phrase","text":"a bit of","targetId":"phrase-a-bit-of","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-055-01"},{"type":"text","text":" a "},{"type":"word","text":"perfectionist","targetId":"word-perfectionist","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-055-02"},{"type":"text","text":", so I will "},{"type":"phrase","text":"go past deadlines","targetId":"phrase-go-past-deadlines","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-055-03"},{"type":"text","text":" "},{"type":"phrase","text":"in order to","targetId":"phrase-in-order-to","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-055-04"},{"type":"text","text":" make the work exactly how I want it."}]},{"en":"What is a deadline?","tc":"什麼是 deadline？","englishTokens":[{"type":"text","text":"What is a "},{"type":"word","text":"deadline","targetId":"word-deadline","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-056-01"},{"type":"text","text":"?"}]}],"tags":[]},{"id":"scene-15","no":"15","titleZh":"第 15 段","titleEn":"Part 15","sentences":[{"en":"A deadline is a due date, um, a timeline or a time when you must hand in an assignment or work.","tc":"Deadline 是截止日期，呃，是時間表，或是你必須繳交作業或工作的時間。","englishTokens":[{"type":"text","text":"A deadline is a "},{"type":"phrase","text":"due date","targetId":"phrase-due-date","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-057-01"},{"type":"text","text":", um, a timeline or a time when you must "},{"type":"phrase","text":"hand in","targetId":"phrase-hand-in","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-057-02"},{"type":"text","text":" an "},{"type":"word","text":"assignment","targetId":"word-assignment","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-057-03"},{"type":"text","text":" or work."}]},{"en":"So I think I'd have to work on my time management.","tc":"所以我想我得改善我的時間管理。","englishTokens":[{"type":"text","text":"So I think I'd have to work on my "},{"type":"phrase","text":"time management","targetId":"phrase-time-management","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-058-01"},{"type":"text","text":"."}]},{"en":"What is time management?","tc":"什麼是 time management？","englishTokens":[{"type":"text","text":"What is "},{"type":"phrase","text":"time management","targetId":"phrase-time-management","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-059-01"},{"type":"text","text":"?"}]},{"en":"Time management is the administration of your time, organizing your time.","tc":"Time management 是對你的時間進行管理，安排你的時間。","englishTokens":[{"type":"text","text":"Time management is the "},{"type":"word","text":"administration","targetId":"word-administration","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-060-01"},{"type":"text","text":" of your time, organizing your time."}]}],"tags":[]},{"id":"scene-16","no":"16","titleZh":"第 16 段","titleEn":"Part 16","sentences":[{"en":"Okay.","tc":"好。","englishTokens":[{"type":"text","text":"Okay."}]},{"en":"Do you have any experience in this field?","tc":"你在這個領域有任何經驗嗎？","englishTokens":[{"type":"text","text":"Do you have any experience in this "},{"type":"usage","text":"field","targetId":"usage-field-item","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-062-01"},{"type":"text","text":"?"}]},{"en":"Yes, I used to work for multiple different English teaching companies, mostly for children.","tc":"有，我以前為多家不同的英語教學公司工作，主要是教孩子。","englishTokens":[{"type":"text","text":"Yes, I "},{"type":"phrase","text":"used to","targetId":"phrase-used-to","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-063-01"},{"type":"text","text":" work for "},{"type":"word","text":"multiple","targetId":"word-multiple","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-063-02"},{"type":"text","text":" different English teaching companies, mostly for children."}]},{"en":"I created lesson plans for grades K through 12.","tc":"我為 K 到 12 年級設計教案。","englishTokens":[{"type":"text","text":"I created "},{"type":"phrase","text":"lesson plans","targetId":"phrase-lesson-plan","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-064-01"},{"type":"text","text":" for grades "},{"type":"phrase","text":"K through 12","targetId":"phrase-k-through-12","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-064-02"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-17","no":"17","titleZh":"第 17 段","titleEn":"Part 17","sentences":[{"en":"I taught ages 3 to 17, and I talked a lot.","tc":"我教過 3 到 17 歲的學生，而且我講了很多話。","englishTokens":[{"type":"text","text":"I taught ages 3 to 17, and I talked a lot."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"And why did you leave your last job?","tc":"那你為什麼離開上一份工作？","englishTokens":[{"type":"text","text":"And why did you leave your last job?"}]},{"en":"I really enjoyed my last job, but I felt it was time for a change.","tc":"我很喜歡上一份工作，但我覺得是時候改變了。","englishTokens":[{"type":"text","text":"I really enjoyed my last job, but I felt it was time for a change."}]}],"tags":[]},{"id":"scene-18","no":"18","titleZh":"第 18 段","titleEn":"Part 18","sentences":[{"en":"I graduated with my physics degree, and I thought it was time to see what else is out there.","tc":"我拿到了物理學位，然後我覺得是時候看看外面還有什麼機會。","englishTokens":[{"type":"text","text":"I graduated with my "},{"type":"word","text":"physics","targetId":"word-physics","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-scene-18-001-001"},{"type":"text","text":" degree, and I thought it was time to see what else is out there."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"Can you work well under pressure?","tc":"你能在壓力下好好工作嗎？","englishTokens":[{"type":"text","text":"Can you work well "},{"type":"phrase","text":"under pressure","targetId":"phrase-under-pressure","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-071-01"},{"type":"text","text":"?"}]},{"en":"I would say I work best under pressure.","tc":"我會說我在壓力下工作得最好。","englishTokens":[{"type":"text","text":"I would say I work best "},{"type":"phrase","text":"under pressure","targetId":"phrase-under-pressure","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-072-01"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-19","no":"19","titleZh":"第 19 段","titleEn":"Part 19","sentences":[{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"Some of my best and fastest work comes when I'm under a lot of pressure.","tc":"我有些最好、最快的作品，是在壓力很大時完成的。","englishTokens":[{"type":"text","text":"Some of my best and fastest work comes when I'm under a lot of "},{"type":"word","text":"pressure","targetId":"word-pressure","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-074-01"},{"type":"text","text":"."}]},{"en":"Can you give me any examples?","tc":"你能給我一些例子嗎？","englishTokens":[{"type":"text","text":"Can you give me any examples?"}]},{"en":"In college, during my molecular physics class, we had to give a video presentation.","tc":"大學時，在我的分子物理課上，我們必須做一個影片報告。","englishTokens":[{"type":"text","text":"In college, during my "},{"type":"word","text":"molecular","targetId":"word-molecular","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-076-01"},{"type":"text","text":" physics class, we had to give a video "},{"type":"word","text":"presentation","targetId":"word-presentation","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-076-02"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-20","no":"20","titleZh":"第 20 段","titleEn":"Part 20","sentences":[{"en":"It was during the pandemic, and I had put off making a script for a long time.","tc":"那是在疫情期間，而我把寫稿這件事拖了很久。","englishTokens":[{"type":"text","text":"It was during the "},{"type":"word","text":"pandemic","targetId":"word-pandemic","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-077-01"},{"type":"text","text":", and I had "},{"type":"phrase","text":"put off","targetId":"phrase-put-off","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-077-02"},{"type":"text","text":" making a "},{"type":"word","text":"script","targetId":"word-script","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-077-03"},{"type":"text","text":" for a long time."}]},{"en":"And the night before, I went and I studied and I wrote and I recorded my presentation, and I got the best grade in the class.","tc":"然後前一晚，我去讀資料、寫稿、錄下我的報告，最後拿到全班最高分。","englishTokens":[{"type":"text","text":"And the night before, I went and I studied and I wrote and I recorded my "},{"type":"word","text":"presentation","targetId":"word-presentation","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-scene-20-002-001"},{"type":"text","text":", and I got the best grade in the class."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"Congratulations.","tc":"恭喜。","englishTokens":[{"type":"text","text":"Congratulations."}]}],"tags":[]},{"id":"scene-21","no":"21","titleZh":"第 21 段","titleEn":"Part 21","sentences":[{"en":"Thank you.","tc":"謝謝。","englishTokens":[{"type":"text","text":"Thank you."}]},{"en":"How do you handle stress or problems at work?","tc":"你如何處理工作上的壓力或問題？","englishTokens":[{"type":"text","text":"How do you "},{"type":"usage","text":"handle","targetId":"usage-handle-item","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-082-01"},{"type":"text","text":" "},{"type":"word","text":"stress","targetId":"word-stress","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-082-02"},{"type":"text","text":" or problems at work?"}]},{"en":"When it comes to teaching, I try to leave my stress outside of my work.","tc":"說到教學，我會試著把壓力留在工作之外。","englishTokens":[{"type":"phrase","text":"When it comes to","targetId":"phrase-when-it-comes-to","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-083-01"},{"type":"text","text":" teaching, I try to leave my "},{"type":"word","text":"stress","targetId":"word-stress","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-083-02"},{"type":"text","text":" outside of my work."}]},{"en":"I don't want my students to feel responsible or to feel the stress that I sometimes carry.","tc":"我不希望我的學生覺得自己有責任，或感受到我有時背負的壓力。","englishTokens":[{"type":"text","text":"I don't want my students to feel "},{"type":"word","text":"responsible","targetId":"word-responsible","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-084-01"},{"type":"text","text":" or to feel the "},{"type":"word","text":"stress","targetId":"word-stress","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-084-02"},{"type":"text","text":" that I sometimes "},{"type":"usage","text":"carry","targetId":"usage-carry-item","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-084-03"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-22","no":"22","titleZh":"第 22 段","titleEn":"Part 22","sentences":[{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"I handle my stress at home by doing my hobbies, exercising, and eating healthy.","tc":"我在家透過做興趣、運動和健康飲食來處理壓力。","englishTokens":[{"type":"text","text":"I handle my "},{"type":"word","text":"stress","targetId":"word-stress","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-086-01"},{"type":"text","text":" at home by doing my hobbies, exercising, and eating healthy."}]},{"en":"Oh, and getting a good night's sleep.","tc":"喔，還有睡個好覺。","englishTokens":[{"type":"text","text":"Oh, and getting a "},{"type":"phrase","text":"good night's sleep","targetId":"phrase-good-night-s-sleep","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-087-01"},{"type":"text","text":"."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]}],"tags":[]},{"id":"scene-23","no":"23","titleZh":"第 23 段","titleEn":"Part 23","sentences":[{"en":"Why should we hire you?","tc":"為什麼我們應該雇用你？","englishTokens":[{"type":"text","text":"Why should we "},{"type":"word","text":"hire","targetId":"word-hire","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-089-01"},{"type":"text","text":" you?"}]},{"en":"I think my greatest strength as a teacher is my patience.","tc":"我認為我身為老師最大的優點是耐心。","englishTokens":[{"type":"text","text":"I think my greatest "},{"type":"word","text":"strength","targetId":"word-strength","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-090-01"},{"type":"text","text":" as a teacher is my "},{"type":"word","text":"patience","targetId":"word-patience","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-090-02"},{"type":"text","text":"."}]},{"en":"And I think the greatest strength in any teacher is patience, because no matter the student, no matter the age, no matter the cultural background, patience is key, and I have a lot of it.","tc":"而且我認為任何老師最大的優點都是耐心，因為不管學生如何、不管年齡如何、不管文化背景如何，耐心都是關鍵，而我有很多耐心。","englishTokens":[{"type":"text","text":"And I think the greatest "},{"type":"word","text":"strength","targetId":"word-strength","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-091-01"},{"type":"text","text":" in any teacher is "},{"type":"word","text":"patience","targetId":"word-patience","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-091-02"},{"type":"text","text":", because "},{"type":"phrase","text":"no matter","targetId":"phrase-no-matter","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-091-03"},{"type":"text","text":" the student, "},{"type":"phrase","text":"no matter","targetId":"phrase-no-matter","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-091-04"},{"type":"text","text":" the age, "},{"type":"phrase","text":"no matter","targetId":"phrase-no-matter","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-091-05"},{"type":"text","text":" the "},{"type":"phrase","text":"cultural background","targetId":"phrase-cultural-background","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-091-06"},{"type":"text","text":", "},{"type":"word","text":"patience","targetId":"word-patience","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-091-07"},{"type":"text","text":" is "},{"type":"usage","text":"key","targetId":"usage-key-item","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-091-08"},{"type":"text","text":", and I have a lot of it."}]},{"en":"How do you work in a team?","tc":"你如何在團隊中工作？","englishTokens":[{"type":"text","text":"How do you work in a team?"}]}],"tags":[]},{"id":"scene-24","no":"24","titleZh":"第 24 段","titleEn":"Part 24","sentences":[{"en":"I work well with others.","tc":"我和別人合作得很好。","englishTokens":[{"type":"text","text":"I "},{"type":"phrase","text":"work well with","targetId":"phrase-work-well-with","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-093-01"},{"type":"text","text":" others."}]},{"en":"I'm a very good listener and a leader when I have to be.","tc":"我很會傾聽，必要時也能當領導者。","englishTokens":[{"type":"text","text":"I'm a very good listener and a leader when I have to be."}]},{"en":"Where do you see yourself in five years?","tc":"你覺得五年後的自己會在哪裡？","englishTokens":[{"type":"text","text":"Where do you "},{"type":"phrase","text":"see yourself in five years","targetId":"phrase-see-yourself-in-five-years","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-095-01"},{"type":"text","text":"?"}]},{"en":"In five years, I hope to be, I don't know, the owner of a house.","tc":"五年後，我希望成為，我不知道，一棟房子的主人。","englishTokens":[{"type":"text","text":"In five years, I hope to be, I don't know, the owner of a house."}]}],"tags":[]},{"id":"scene-25","no":"25","titleZh":"第 25 段","titleEn":"Part 25","sentences":[{"en":"I think asking for that is too much.","tc":"我覺得要求那個太多了。","englishTokens":[{"type":"text","text":"I think asking for that is too much."}]},{"en":"I think it's unrealistic.","tc":"我覺得那不切實際。","englishTokens":[{"type":"text","text":"I think it's "},{"type":"word","text":"unrealistic","targetId":"word-unrealistic","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-098-01"},{"type":"text","text":"."}]},{"en":"It used to be a realistic thing, and now it's, like, unrealistic.","tc":"那以前是很實際的事，但現在就像是不切實際。","englishTokens":[{"type":"text","text":"It used to be a "},{"type":"word","text":"realistic","targetId":"word-realistic","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-099-01"},{"type":"text","text":" thing, and now it's, like, "},{"type":"word","text":"unrealistic","targetId":"word-unrealistic","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-099-02"},{"type":"text","text":"."}]},{"en":"There are different things that, like, are doable in five years, you know.","tc":"有些事情在五年內是做得到的，你知道。","englishTokens":[{"type":"text","text":"There are different things that, like, are "},{"type":"word","text":"doable","targetId":"word-doable","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-100-01"},{"type":"text","text":" in five years, you know."}]}],"tags":[]},{"id":"scene-26","no":"26","titleZh":"第 26 段","titleEn":"Part 26","sentences":[{"en":"I guess in five years, I'd like to explore more of my hobbies.","tc":"我想五年後，我會想探索更多我的興趣。","englishTokens":[{"type":"text","text":"I guess in five years, I'd like to explore more of my "},{"type":"word","text":"hobbies","targetId":"word-hobby","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-scene-26-001-001"},{"type":"text","text":"."}]},{"en":"I hope to know at least four languages within five years.","tc":"我希望五年內至少會四種語言。","englishTokens":[{"type":"text","text":"I hope to know at least four languages within five years."}]},{"en":"Um, I'm currently working toward those goals.","tc":"呃，我目前正朝那些目標努力。","englishTokens":[{"type":"text","text":"Um, I'm "},{"type":"word","text":"currently","targetId":"word-currently","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-103-01"},{"type":"text","text":" working toward those goals."}]},{"en":"I hope, a big hope, to have a house or at least be looking into buying a house.","tc":"我希望，這是很大的願望，能有一棟房子，或至少正在考慮買房子。","englishTokens":[{"type":"text","text":"I hope, a big hope, to have a house or at least be "},{"type":"phrase","text":"looking into","targetId":"phrase-look-into","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-104-01"},{"type":"text","text":" buying a house."}]}],"tags":[]},{"id":"scene-27","no":"27","titleZh":"第 27 段","titleEn":"Part 27","sentences":[{"en":"And I'd like to maybe open a YouTube channel.","tc":"然後我可能想開一個 YouTube 頻道。","englishTokens":[{"type":"text","text":"And I'd like to maybe open a YouTube channel."}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]},{"en":"Since video editing has always been a passion of mine.","tc":"因為影片剪輯一直是我的熱情。","englishTokens":[{"type":"text","text":"Since "},{"type":"phrase","text":"video editing","targetId":"phrase-video-editing","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-107-01"},{"type":"text","text":" has always been a "},{"type":"word","text":"passion","targetId":"word-passion","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-107-02"},{"type":"text","text":" of mine."}]},{"en":"What would your videos be about?","tc":"你的影片會是關於什麼？","englishTokens":[{"type":"text","text":"What would your videos be about?"}]}],"tags":[]},{"id":"scene-28","no":"28","titleZh":"第 28 段","titleEn":"Part 28","sentences":[{"en":"Probably vlogs and philosophical topics, since I enjoy reading philosophy and looking back at my own life and remembering to be grateful.","tc":"可能是影音日誌和哲學主題，因為我喜歡讀哲學，也喜歡回顧自己的人生，並記得保持感恩。","englishTokens":[{"type":"text","text":"Probably "},{"type":"word","text":"vlogs","targetId":"word-vlog","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-109-01"},{"type":"text","text":" and "},{"type":"word","text":"philosophical","targetId":"word-philosophical","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-109-02"},{"type":"text","text":" "},{"type":"word","text":"topics","targetId":"word-topic","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-109-03"},{"type":"text","text":", since I enjoy reading "},{"type":"word","text":"philosophy","targetId":"word-philosophy","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-109-04"},{"type":"text","text":" and "},{"type":"phrase","text":"looking back at","targetId":"phrase-look-back-at","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-109-05"},{"type":"text","text":" my own life and remembering to be "},{"type":"word","text":"grateful","targetId":"word-grateful","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-109-06"},{"type":"text","text":"."}]},{"en":"Nice.","tc":"很好。","englishTokens":[{"type":"text","text":"Nice."}]},{"en":"Do you have any questions for me?","tc":"你有任何問題要問我嗎？","englishTokens":[{"type":"text","text":"Do you have any questions for me?"}]},{"en":"For this question, it's important to remember that you should ask something back.","tc":"對於這個問題，重要的是要記得你應該反過來問一些事情。","englishTokens":[{"type":"text","text":"For this question, it's important to remember that you should ask something back."}]}],"tags":[]},{"id":"scene-29","no":"29","titleZh":"第 29 段","titleEn":"Part 29","sentences":[{"en":"In the United States, it's common and important to ask any questions you might have for the interviewer.","tc":"在美國，向面試官提出任何你可能有的問題是常見且重要的。","englishTokens":[{"type":"text","text":"In the United States, it's common and important to ask any questions you might have for the "},{"type":"word","text":"interviewer","targetId":"word-interviewer","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-scene-29-001-001"},{"type":"text","text":"."}]},{"en":"I would like to ask about the work environment.","tc":"我想問一下工作環境。","englishTokens":[{"type":"text","text":"I would like to ask about the "},{"type":"phrase","text":"work environment","targetId":"phrase-work-environment","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-114-01"},{"type":"text","text":"."}]},{"en":"What is it like in your company?","tc":"你們公司的工作環境是什麼樣子？","englishTokens":[{"type":"text","text":"What is it like in your company?"}]},{"en":"Mhm.","tc":"嗯。","englishTokens":[{"type":"text","text":"Mhm."}]}],"tags":[]},{"id":"scene-30","no":"30","titleZh":"第 30 段","titleEn":"Part 30","sentences":[{"en":"Our work environment is a very dynamic and social environment.","tc":"我們的工作環境是非常有活力、也很社交的環境。","englishTokens":[{"type":"text","text":"Our work environment is a very "},{"type":"word","text":"dynamic","targetId":"word-dynamic","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-117-01"},{"type":"text","text":" and social environment."}]},{"en":"So, it's not important for you to be very social, but if you are, you'll have a good time.","tc":"所以，你不一定要非常社交，但如果你是，你會過得很愉快。","englishTokens":[{"type":"text","text":"So, it's not important for you to be very social, but if you are, you'll have a good time."}]},{"en":"Where do you see this company going in five years, and how can I be a part of that?","tc":"你覺得這家公司五年後會走向哪裡，而我可以如何成為其中一部分？","englishTokens":[{"type":"text","text":"Where do you see this company going in five years, and how can I be a part of that?"}]},{"en":"Well, we're a slow startup, but we're hoping to branch out in the next few years and hopefully have you leading a team of teachers in the future.","tc":"嗯，我們是一家慢慢發展的新創公司，但我們希望未來幾年能擴展業務，也希望未來能讓你帶領一個教師團隊。","englishTokens":[{"type":"text","text":"Well, we're a slow "},{"type":"word","text":"startup","targetId":"word-startup","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-120-01"},{"type":"text","text":", but we're hoping to "},{"type":"phrase","text":"branch out","targetId":"phrase-branch-out","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-120-02"},{"type":"text","text":" in the next few years and hopefully have you leading a team of teachers in the future."}]}],"tags":[]},{"id":"scene-31","no":"31","titleZh":"第 31 段","titleEn":"Part 31","sentences":[{"en":"Thank you for helping us practice essential job interview vocabulary, and let me know in the comments if you would like to see my sister Brianna again.","tc":"謝謝你幫助我們練習求職面試必備詞彙，如果你想再看到我的妹妹 Brianna，請在留言裡告訴我。","englishTokens":[{"type":"text","text":"Thank you for helping us practice "},{"type":"word","text":"essential","targetId":"word-essential","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-121-01"},{"type":"text","text":" "},{"type":"phrase","text":"job interview","targetId":"phrase-job-interview","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-121-02"},{"type":"text","text":" "},{"type":"word","text":"vocabulary","targetId":"word-vocabulary","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-121-03"},{"type":"text","text":", and let me know in the comments if you would like to see my sister Brianna again."}]},{"en":"Thank you for watching.","tc":"謝謝收看。","englishTokens":[{"type":"text","text":"Thank you for watching."}]},{"en":"Bye.","tc":"再見。","englishTokens":[{"type":"text","text":"Bye."}]},{"en":"That's like my journal, and I left it in there.","tc":"那就像我的日記，我把它留在那裡了。","englishTokens":[{"type":"text","text":"That's like my "},{"type":"word","text":"journal","targetId":"word-journal","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-124-01"},{"type":"text","text":", and I left it in there."}]}],"tags":[]},{"id":"scene-32","no":"32","titleZh":"第 32 段","titleEn":"Part 32","sentences":[{"en":"Um, pick-up lines.","tc":"呃，搭訕台詞。","englishTokens":[{"type":"text","text":"Um, "},{"type":"phrase","text":"pick-up lines","targetId":"phrase-pick-up-line","instanceId":"marker-b1-ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice-125-01"},{"type":"text","text":"."}]},{"en":"Yeah.","tc":"對。","englishTokens":[{"type":"text","text":"Yeah."}]}],"tags":[]}]`),s=[{title:"B1 重點單字",items:[{id:"word-essential",lemma:"essential",english:"Essential; essential",kk:"/ɪˈsɛnʃəl/",partOfSpeech:"adjective",meaning:"必備的；重要的",highlight:!0},{id:"word-vocabulary",lemma:"vocabulary",english:"vocabulary",kk:"/voˈkæbjəˌlɛri/",partOfSpeech:"noun",meaning:"詞彙",highlight:!0},{id:"word-podcast",lemma:"podcast",english:"podcast",kk:"/ˈpɑdˌkæst/",partOfSpeech:"noun",meaning:"Podcast；播客節目",highlight:!0},{id:"word-interviewer",lemma:"interviewer",english:"interviewer",kk:"/ˈɪntɚˌvjuɚ/",partOfSpeech:"noun",meaning:"面試官；訪問者",highlight:!0},{id:"word-extensive",lemma:"extensive",english:"extensive",kk:"/ɪkˈstɛnsɪv/",partOfSpeech:"adjective",meaning:"大量的；廣泛的",highlight:!0},{id:"word-minimal",lemma:"minimal",english:"minimal",kk:"/ˈmɪnəməl/",partOfSpeech:"adjective",meaning:"很少的；最低限度的",highlight:!0},{id:"word-interviewee",lemma:"interviewee",english:"interviewee",kk:"/ˌɪntɚvjuˈi/",partOfSpeech:"noun",meaning:"受訪者；應徵者",highlight:!0},{id:"word-physics",lemma:"physics",english:"physics",kk:"/ˈfɪzɪks/",partOfSpeech:"noun",meaning:"物理學",highlight:!0},{id:"word-copywriting",lemma:"copywriting",english:"copywriting",kk:"/ˈkɑpiˌraɪtɪŋ/",partOfSpeech:"noun",meaning:"文案寫作",highlight:!0},{id:"word-hobby",lemma:"hobby",english:"hobbies",kk:"/ˈhɑbi/",partOfSpeech:"noun",meaning:"興趣；嗜好",highlight:!0},{id:"word-knowledgeable",lemma:"knowledgeable",english:"knowledgeable",kk:"/ˈnɑlɪdʒəbəl/",partOfSpeech:"adjective",meaning:"知識豐富的",highlight:!0},{id:"word-environment",lemma:"environment",english:"environment",kk:"/ɪnˈvaɪrənmənt/",partOfSpeech:"noun",meaning:"環境",highlight:!0},{id:"word-honesty",lemma:"honesty",english:"honesty",kk:"/ˈɑnəsti/",partOfSpeech:"noun",meaning:"誠實",highlight:!0},{id:"word-loyalty",lemma:"loyalty",english:"loyalty",kk:"/ˈlɔɪəlti/",partOfSpeech:"noun",meaning:"忠誠",highlight:!0},{id:"word-patience",lemma:"patience",english:"patience",kk:"/ˈpeʃəns/",partOfSpeech:"noun",meaning:"耐心",highlight:!0},{id:"word-strength",lemma:"strength",english:"strengths; strength",kk:"/strɛŋθ/",partOfSpeech:"noun",meaning:"優點；長處",highlight:!0},{id:"word-punctual",lemma:"punctual",english:"punctual",kk:"/ˈpʌŋktʃuəl/",partOfSpeech:"adjective",meaning:"準時的",highlight:!0},{id:"word-thorough",lemma:"thorough",english:"thorough",kk:"/ˈθɝo/",partOfSpeech:"adjective",meaning:"徹底的；仔細的",highlight:!0},{id:"word-exhaustive",lemma:"exhaustive",english:"exhaustive",kk:"/ɪgˈzɔstɪv/",partOfSpeech:"adjective",meaning:"詳盡的；徹底的",highlight:!0},{id:"word-weakness",lemma:"weakness",english:"weaknesses",kk:"/ˈwiknɪs/",partOfSpeech:"noun",meaning:"弱點",highlight:!0},{id:"word-soft-spoken",lemma:"soft-spoken",english:"soft-spoken",kk:"/ˌsɔftˈspokən/",partOfSpeech:"adjective",meaning:"說話溫和的；輕聲細語的",highlight:!0},{id:"word-perfectionist",lemma:"perfectionist",english:"perfectionist",kk:"/pɚˈfɛkʃənɪst/",partOfSpeech:"noun",meaning:"完美主義者",highlight:!0},{id:"word-deadline",lemma:"deadline",english:"deadline",kk:"/ˈdɛdˌlaɪn/",partOfSpeech:"noun",meaning:"截止期限",highlight:!0},{id:"word-assignment",lemma:"assignment",english:"assignment",kk:"/əˈsaɪnmənt/",partOfSpeech:"noun",meaning:"作業；任務",highlight:!0},{id:"word-administration",lemma:"administration",english:"administration",kk:"/ədˌmɪnəˈstreʃən/",partOfSpeech:"noun",meaning:"管理；行政",highlight:!0},{id:"word-multiple",lemma:"multiple",english:"multiple",kk:"/ˈmʌltəpəl/",partOfSpeech:"adjective",meaning:"多個的",highlight:!0},{id:"word-pressure",lemma:"pressure",english:"pressure",kk:"/ˈprɛʃɚ/",partOfSpeech:"noun",meaning:"壓力",highlight:!0},{id:"word-molecular",lemma:"molecular",english:"molecular",kk:"/məˈlɛkjəlɚ/",partOfSpeech:"adjective",meaning:"分子的",highlight:!0},{id:"word-presentation",lemma:"presentation",english:"presentation",kk:"/ˌprizɛnˈteʃən/",partOfSpeech:"noun",meaning:"報告；簡報",highlight:!0},{id:"word-pandemic",lemma:"pandemic",english:"pandemic",kk:"/pænˈdɛmɪk/",partOfSpeech:"noun",meaning:"疫情；大流行病",highlight:!0},{id:"word-script",lemma:"script",english:"script",kk:"/skrɪpt/",partOfSpeech:"noun",meaning:"稿子；腳本",highlight:!0},{id:"word-stress",lemma:"stress",english:"stress",kk:"/strɛs/",partOfSpeech:"noun",meaning:"壓力",highlight:!0},{id:"word-responsible",lemma:"responsible",english:"responsible",kk:"/rɪˈspɑnsəbəl/",partOfSpeech:"adjective",meaning:"負責的；有責任的",highlight:!0},{id:"word-hire",lemma:"hire",english:"hire",kk:"/haɪr/",partOfSpeech:"verb",meaning:"雇用",highlight:!0},{id:"word-unrealistic",lemma:"unrealistic",english:"unrealistic",kk:"/ˌʌnriəˈlɪstɪk/",partOfSpeech:"adjective",meaning:"不切實際的",highlight:!0},{id:"word-realistic",lemma:"realistic",english:"realistic",kk:"/ˌriəˈlɪstɪk/",partOfSpeech:"adjective",meaning:"實際的；現實可行的",highlight:!0},{id:"word-doable",lemma:"doable",english:"doable",kk:"/ˈduəbəl/",partOfSpeech:"adjective",meaning:"做得到的；可行的",highlight:!0},{id:"word-currently",lemma:"currently",english:"currently",kk:"/ˈkɝəntli/",partOfSpeech:"adverb",meaning:"目前",highlight:!0},{id:"word-passion",lemma:"passion",english:"passion",kk:"/ˈpæʃən/",partOfSpeech:"noun",meaning:"熱情；熱愛的事物",highlight:!0},{id:"word-vlog",lemma:"vlog",english:"vlogs",kk:"/vlɑg/",partOfSpeech:"noun",meaning:"影音日誌",highlight:!0},{id:"word-philosophical",lemma:"philosophical",english:"philosophical",kk:"/ˌfɪləˈsɑfɪkəl/",partOfSpeech:"adjective",meaning:"哲學的",highlight:!0},{id:"word-topic",lemma:"topic",english:"topics",kk:"/ˈtɑpɪk/",partOfSpeech:"noun",meaning:"主題",highlight:!0},{id:"word-philosophy",lemma:"philosophy",english:"philosophy",kk:"/fəˈlɑsəfi/",partOfSpeech:"noun",meaning:"哲學",highlight:!0},{id:"word-grateful",lemma:"grateful",english:"grateful",kk:"/ˈgretfəl/",partOfSpeech:"adjective",meaning:"感恩的",highlight:!0},{id:"word-dynamic",lemma:"dynamic",english:"dynamic",kk:"/daɪˈnæmɪk/",partOfSpeech:"adjective",meaning:"有活力的；多變的",highlight:!0},{id:"word-startup",lemma:"startup",english:"startup",kk:"/ˈstɑrtˌʌp/",partOfSpeech:"noun",meaning:"新創公司",highlight:!0},{id:"word-journal",lemma:"journal",english:"journal",kk:"/ˈdʒɝnəl/",partOfSpeech:"noun",meaning:"日記；紀錄本",highlight:!0}]}],o=[{id:"phrase-see-yourself-in-five-years",phrase:"see yourself in five years",meaning:"想像自己五年後的狀態或位置",examples:[{en:"Where do you see yourself in five years?",tc:"想像自己五年後的狀態或位置"}]},{id:"phrase-job-interview",phrase:"job interview",meaning:"求職面試",examples:[{en:"Essential job interview vocabulary.",tc:"求職面試"}]},{id:"phrase-listening-skills",phrase:"listening skills",meaning:"聽懂語言的能力",examples:[{en:"Practice your English listening skills.",tc:"聽懂語言的能力"}]},{id:"phrase-hard-worker",phrase:"hard worker",meaning:"工作認真努力的人",examples:[{en:"I'm a hard worker.",tc:"工作認真努力的人"}]},{id:"phrase-on-time",phrase:"on time",meaning:"準時",examples:[{en:"I'm always on time.",tc:"準時"}]},{id:"phrase-a-little-bit",phrase:"a little bit",meaning:"一點點；簡短地",examples:[{en:"Can you tell me a little bit about yourself?",tc:"一點點；簡短地"}]},{id:"phrase-bachelor-s-degree",phrase:"bachelor's degree",meaning:"大學學士學位",examples:[{en:"I have a bachelor's degree in physics.",tc:"大學學士學位"}]},{id:"phrase-have-a-background-in",phrase:"have a background in",meaning:"在某領域有過去的學習或工作經驗",examples:[{en:"I have a background in English teaching.",tc:"在某領域有過去的學習或工作經驗"}]},{id:"phrase-based-in",phrase:"based in",meaning:"位於；住在；以某地為所在地",examples:[{en:"Kids based in China.",tc:"位於；住在；以某地為所在地"}]},{id:"phrase-k-through-12",phrase:"K through 12",meaning:"美式教育中從幼稚園到高中十二年級",examples:[{en:"Grades K through 12.",tc:"美式教育中從幼稚園到高中十二年級"}]},{id:"phrase-along-the-way",phrase:"along the way",meaning:"在過程中；一路上",examples:[{en:"Skills you've gained along the way.",tc:"在過程中；一路上"}]},{id:"phrase-get-to-know",phrase:"get to know",meaning:"逐漸認識；了解",examples:[{en:"Getting to know people.",tc:"逐漸認識；了解"}]},{id:"phrase-learning-process",phrase:"learning process",meaning:"學習的整個過程",examples:[{en:"Helping in the learning process.",tc:"學習的整個過程"}]},{id:"phrase-move-along",phrase:"move along",meaning:"事情繼續進展",examples:[{en:"As we move along.",tc:"事情繼續進展"}]},{id:"phrase-core-values",phrase:"core values",meaning:"最重要的信念或原則",examples:[{en:"My core values are honesty, loyalty, and patience.",tc:"最重要的信念或原則"}]},{id:"phrase-team-leader",phrase:"team leader",meaning:"帶領團隊的人",examples:[{en:"I am a good team leader.",tc:"帶領團隊的人"}]},{id:"phrase-classroom-management",phrase:"classroom management",meaning:"維持課堂秩序與學習氣氛的能力",examples:[{en:"This can sometimes show in classroom management.",tc:"維持課堂秩序與學習氣氛的能力"}]},{id:"phrase-a-bit-of",phrase:"a bit of",meaning:"有點；稍微",examples:[{en:"A bit of a perfectionist.",tc:"有點；稍微"}]},{id:"phrase-go-past-deadlines",phrase:"go past deadlines",meaning:"超過截止期限；逾期",examples:[{en:"I will go past deadlines.",tc:"超過截止期限；逾期"}]},{id:"phrase-in-order-to",phrase:"in order to",meaning:"表示目的",examples:[{en:"In order to make the work exactly how I want it.",tc:"表示目的"}]},{id:"phrase-due-date",phrase:"due date",meaning:"必須完成或繳交的日期",examples:[{en:"A deadline is a due date.",tc:"必須完成或繳交的日期"}]},{id:"phrase-hand-in",phrase:"hand in",meaning:"繳交",examples:[{en:"You must hand in an assignment.",tc:"繳交"}]},{id:"phrase-time-management",phrase:"time management",meaning:"安排並控制自己時間的能力",examples:[{en:"I think I'd have to work on my time management.",tc:"安排並控制自己時間的能力"}]},{id:"phrase-used-to",phrase:"used to",meaning:"以前常常或曾經做某事，現在通常不做了",examples:[{en:"I used to work for multiple different English teaching companies.",tc:"以前常常或曾經做某事，現在通常不做了"}]},{id:"phrase-lesson-plan",phrase:"lesson plan",meaning:"上課前設計好的教學內容與步驟",examples:[{en:"I created lesson plans for grades K through 12.",tc:"上課前設計好的教學內容與步驟"}]},{id:"phrase-under-pressure",phrase:"under pressure",meaning:"處於壓力狀態",examples:[{en:"Can you work well under pressure?",tc:"處於壓力狀態"}]},{id:"phrase-put-off",phrase:"put off",meaning:"拖延；延後做",examples:[{en:"I had put off making a script for a long time.",tc:"拖延；延後做"}]},{id:"phrase-when-it-comes-to",phrase:"when it comes to",meaning:"說到；談到某主題時",examples:[{en:"When it comes to teaching, I try to leave my stress outside of my work.",tc:"說到；談到某主題時"}]},{id:"phrase-good-night-s-sleep",phrase:"good night's sleep",meaning:"睡得好、睡眠充足的一晚",examples:[{en:"Getting a good night's sleep.",tc:"睡得好、睡眠充足的一晚"}]},{id:"phrase-no-matter",phrase:"no matter",meaning:"無論；不管",examples:[{en:"No matter the student, no matter the age, no matter the cultural background.",tc:"無論；不管"}]},{id:"phrase-cultural-background",phrase:"cultural background",meaning:"一個人的文化出身或文化環境",examples:[{en:"No matter the cultural background.",tc:"一個人的文化出身或文化環境"}]},{id:"phrase-work-well-with",phrase:"work well with",meaning:"能與某人良好合作",examples:[{en:"I work well with others.",tc:"能與某人良好合作"}]},{id:"phrase-look-into",phrase:"look into",meaning:"研究、考慮或調查",examples:[{en:"Looking into buying a house.",tc:"研究、考慮或調查"}]},{id:"phrase-video-editing",phrase:"video editing",meaning:"剪接與編輯影片",examples:[{en:"Video editing has always been a passion of mine.",tc:"剪接與編輯影片"}]},{id:"phrase-look-back-at",phrase:"look back at",meaning:"回顧；回想",examples:[{en:"Looking back at my own life.",tc:"回顧；回想"}]},{id:"phrase-work-environment",phrase:"work environment",meaning:"工作的場所氛圍與條件",examples:[{en:"I would like to ask about the work environment.",tc:"工作的場所氛圍與條件"}]},{id:"phrase-branch-out",phrase:"branch out",meaning:"擴展到新的領域或業務",examples:[{en:"We're hoping to branch out in the next few years.",tc:"擴展到新的領域或業務"}]},{id:"phrase-pick-up-line",phrase:"pick-up line",meaning:"用來搭訕或引起對方注意的話",examples:[{en:"Um, pick-up lines.",tc:"用來搭訕或引起對方注意的話"}]}],h=[{id:"usage-background-item",word:"background",familiarMeaning:"背景；後面的景物",usage:"指一個人過去的工作、學習或經驗背景",translation:"背景；經歷",examples:["What do we mean when we say background?"]},{id:"usage-area-item",word:"area",familiarMeaning:"區域；地方",usage:"指學科、工作或興趣的領域",translation:"領域",examples:["Some of my interests are in the science area."]},{id:"usage-show-item",word:"show",familiarMeaning:"展示；表演",usage:"指某種情況顯現或表現在某方面",translation:"表現出來；顯現",examples:["This can sometimes show in classroom management."]},{id:"usage-field-item",word:"field",familiarMeaning:"田地；場地",usage:"指工作、研究或專業領域",translation:"領域",examples:["Do you have any experience in this field?"]},{id:"usage-handle-item",word:"handle",familiarMeaning:"把手；用手拿",usage:"作動詞時表示處理問題、壓力或情況",translation:"處理；應付",examples:["How do you handle stress or problems at work?"]},{id:"usage-carry-item",word:"carry",familiarMeaning:"攜帶；搬運",usage:"指承受或背負情緒、壓力、責任",translation:"背負；承受",examples:["The stress that I sometimes carry."]},{id:"usage-key-item",word:"key",familiarMeaning:"鑰匙",usage:"作形容詞或名詞時表示最重要的事物、關鍵",translation:"關鍵",examples:["Patience is key."]}],l=[{id:"grammar-1",sentence:"Where do you see yourself in five years?",translation:"你覺得五年後的自己會在哪裡？",points:[{label:"Wh-question with reflexive pronoun and future time phrase",text:"Where + do + subject + verb + reflexive pronoun + future time phrase?",note:"see yourself 表示想像自己處在某種狀態，in five years 表示五年後。"}]},{id:"grammar-2",sentence:"Today, I'm excited to have another slow English interview with my sister to practice asking questions and answering them with new vocabulary essential for a job interview, so you can practice your English listening skills by listening to slow English conversations.",translation:"透過聽慢速英語對話來練習英文聽力技巧。",points:[{label:"By + gerund for method",text:"by + V-ing",note:"by listening 表示練習英文聽力的方法是聽慢速英語對話。"}]},{id:"grammar-3",sentence:"I personally get really nervous at job interviews, even though I'm a hard worker and a good learner, and I'm always on time.",translation:"即使我是個努力工作的人、學習能力也好，而且總是準時。",points:[{label:"Even though concession clause",text:"even though + subject + verb",note:"even though 用來表示讓步，意思是「即使」。"}]},{id:"grammar-4",sentence:"They need to determine if you have extensive experience or minimal experience.",translation:"他們需要判斷你是有豐富經驗還是經驗很少。",points:[{label:"If-clause as noun clause",text:"determine + if + subject + verb",note:"這裡的 if 不是條件，而是 whether 的意思，作為 determine 的受詞。"}]},{id:"grammar-5",sentence:"I've been an English teacher for five years.",translation:"我當英文老師已經五年了。",points:[{label:"Present perfect with for",text:"have/has + past participle + for + time period",note:"用現在完成式表示從過去開始並持續到現在的狀態。"}]},{id:"grammar-6",sentence:"I would love to teach English biology, English physics, or even English chemistry.",translation:"我很想教英文生物、英文物理，甚至英文化學。",points:[{label:"Would love to + verb",text:"would love to + base verb",note:"would love to 比 want to 更委婉，表示很想做某事。"}]},{id:"grammar-7",sentence:"Sometimes I can be a bit of a perfectionist, so I will go past deadlines in order to make the work exactly how I want it.",translation:"為了把作品做到完全符合我想要的樣子。",points:[{label:"In order to for purpose",text:"in order to + base verb",note:"in order to 用來說明做某件事的目的。"}]},{id:"grammar-8",sentence:"Yes, I used to work for multiple different English teaching companies, mostly for children.",translation:"我以前為多家不同的英語教學公司工作。",points:[{label:"Used to + base verb",text:"used to + base verb",note:"used to 表示過去曾經常做某事，但現在通常已不再如此。"}]},{id:"grammar-9",sentence:"It was during the pandemic, and I had put off making a script for a long time.",translation:"我把寫稿這件事拖了很久。",points:[{label:"Past perfect",text:"had + past participle",note:"had put off 表示在另一個過去時間點以前，拖延這件事已經發生並持續了一段時間。"}]},{id:"grammar-10",sentence:"When it comes to teaching, I try to leave my stress outside of my work.",translation:"說到教學，我會試著把壓力留在工作之外。",points:[{label:"When it comes to + gerund/noun",text:"When it comes to + noun/V-ing, clause",note:"這個句型用來引出談論的主題，意思是「說到……」。"}]},{id:"grammar-11",sentence:"And I think the greatest strength in any teacher is patience, because no matter the student, no matter the age, no matter the cultural background, patience is key, and I have a lot of it.",translation:"不管學生如何、不管年齡如何、不管文化背景如何。",points:[{label:"No matter + noun phrase",text:"no matter + noun phrase",note:"no matter 後面接名詞片語時，表示「無論是哪一種……」。"}]},{id:"grammar-12",sentence:"Since video editing has always been a passion of mine.",translation:"因為影片剪輯一直是我的熱情。",points:[{label:"Since as reason with present perfect",text:"since + subject + has/have + past participle",note:"since 在這裡表示原因；has always been 表示從過去到現在一直都是。"}]},{id:"grammar-13",sentence:"For this question, it's important to remember that you should ask something back.",translation:"重要的是要記得你應該反過來問一些事情。",points:[{label:"Dummy it + adjective + to-infinitive",text:"it is + adjective + to + verb",note:"it 是形式主詞，真正的主詞是後面的 to remember that you should ask something back。"}]},{id:"grammar-14",sentence:"We're hoping to branch out in the next few years and hopefully have you leading a team of teachers in the future.",translation:"希望未來能讓你帶領一個教師團隊。",points:[{label:"Have + object + present participle",text:"have + object + V-ing",note:"have you leading 表示安排或希望讓你處於帶領團隊的狀態。"}]}],p={level:"b1",slug:"ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice",sourcePath:"_private/tmp/originalContent/b1/ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice.json",proofreadPath:"C:/Users/Gary/Documents/Slowy_Learning_Eng/_private/tmp/step1/b1/ch10-learn-english-with-slow-interviews-comprehensible-input-b1-interview-practice.md"},g={videoId:e,slug:t,level:"b1",title:n,youtubeUrl:i,header:r,scenes:a,vocabGroups:s,phrases:o,usages:h,breakdowns:l,sourceTraceability:p};export{l as breakdowns,g as default,r as header,c as level,o as phrases,a as scenes,t as slug,p as sourceTraceability,n as title,h as usages,e as videoId,s as vocabGroups,i as youtubeUrl};
